#!/usr/bin/env node
// Generate src/app/refs.js: the reference photographs the app may show in
// "compare", and their credit lines.
//
//   node tools/refs.mjs           write src/app/refs.js
//   node tools/refs.mjs --check   exit 1 if src/app/refs.js is out of date (smoke runs this)
//
// Only the photographs a registered artifact names as a view `ref` are listed,
// so Vite emits exactly those (reference/ holds ~20 MB, comparanda included).
// Vite needs import.meta.glob patterns to be literal, hence a generated file.
// Credits are read from reference/<id>/SOURCES.md: a per-file table row with a
// credit/author column (and licence), else the file's "Credit line:" paragraph.
import { readFileSync, writeFileSync, existsSync } from 'node:fs'
import { join } from 'node:path'
import { fileURLToPath } from 'node:url'

const PKG = join(fileURLToPath(new URL('.', import.meta.url)), '..')
const OUT = join(PKG, 'src', 'app', 'refs.js')

/** id → [ref file names], from the registered artifact sources (views' `ref: '…'`). */
export function scanRefs() {
  const index = readFileSync(join(PKG, 'src', 'artifacts', 'index.js'), 'utf8')
  const files = [...index.matchAll(/from\s+['"]\.\/([^'"]+\.js)['"]/g)].map((m) => m[1])
  const out = {}
  for (const f of files) {
    const src = readFileSync(join(PKG, 'src', 'artifacts', f), 'utf8')
    const id = src.match(/\bid:\s*['"]([^'"]+)['"]/)?.[1] || f.replace(/\.js$/, '')
    const refs = [...new Set([...src.matchAll(/\bref:\s*['"]([^'"]+)['"]/g)].map((m) => m[1]))]
    const present = refs.filter((r) => existsSync(join(PKG, 'reference', id, r)))
    if (present.length) out[id] = present.sort()
  }
  return out
}

const clean = (s) =>
  String(s || '')
    .replace(/\*\*|__|`/g, '')
    .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1')
    .replace(/\s+/g, ' ')
    .trim()

/** Credit line for reference/<id>/<file>. */
export function creditFor(id, file) {
  // a flattened face (reference/<id>/faces/<face>.jpg, KIT.md § Flat faces) carries its source photograph's credit
  const face = /^faces\/(.+)\.jpg$/.exec(file)
  const fj = join(PKG, 'reference', id, 'faces.json')
  if (face && existsSync(fj)) {
    try {
      const d = JSON.parse(readFileSync(fj, 'utf8'))
      const src = d.sources?.[d.faces?.[face[1]]?.source]
      if (src?.file) return creditFor(id, src.file) + ' · flattened to a head-on face'
    } catch {
      /* fall through to the folder's credit */
    }
  }
  const p = join(PKG, 'reference', id, 'SOURCES.md')
  if (!existsSync(p)) return `reference/${id}/${file}`
  const md = readFileSync(p, 'utf8')
  const lines = md.split('\n')
  // per-file table rows (houmuwu: commons authors; nezu: the owner's photo)
  let header = null
  for (const line of lines) {
    if (!line.trim().startsWith('|')) {
      header = null
      continue
    }
    const cells = line.split('|').slice(1, -1).map((c) => c.trim())
    if (!header) {
      header = cells.map((c) => c.toLowerCase())
      continue
    }
    if (/^-+$/.test(cells[0].replace(/[:\s]/g, ''))) continue
    if (clean(cells[0]) !== file) continue
    const col = (re) => header.findIndex((h) => re.test(h))
    const ci = col(/credit|author/)
    if (ci < 0) break // a table without a credit column (the Met's): use the paragraph
    let credit = clean(cells[ci])
    const quoted = credit.match(/"([^"]+)"/)
    if (quoted) credit = quoted[1]
    const li = col(/licen/)
    const licence = li >= 0 ? clean(cells[li]) : ''
    const commons = cells.some((c) => /commons\.wikimedia/.test(c)) ? 'Wikimedia Commons' : ''
    const parts = [credit]
    if (licence && !credit.includes(licence)) parts.push(licence)
    if (commons && !credit.includes('Wikimedia')) parts.push(commons)
    return parts.join(' · ')
  }
  // a "Credit line:" paragraph for the whole folder (the Met's open-access photographs)
  const i = lines.findIndex((l) => /credit line:/i.test(l))
  if (i >= 0) {
    const para = []
    for (let k = i; k < lines.length && lines[k].trim(); k++) para.push(lines[k])
    return clean(para.join(' ')).replace(/^credit line:\s*/i, '')
  }
  return `reference/${id}/${file}`
}

export function generate() {
  const refs = scanRefs()
  const paths = []
  const credits = {}
  for (const [id, files] of Object.entries(refs).sort(([a], [b]) => a.localeCompare(b))) {
    for (const f of files) {
      paths.push(`../../reference/${id}/${f}`)
      credits[`${id}/${f}`] = creditFor(id, f)
    }
  }
  return `// GENERATED by tools/refs.mjs from the views' \`ref\` fields and reference/*/SOURCES.md.
// Do not edit by hand: run \`node tools/refs.mjs\` after adding or renaming a view ref
// (tools/smoke.mjs fails while this file is stale). Only these photographs are emitted.

export const REF_URLS = import.meta.glob(
  [
${paths.map((p) => `    ${JSON.stringify(p)},`).join('\n')}
  ],
  // eager: only the URL strings are in the bundle; a photograph is fetched when compare shows it
  { query: '?url', import: 'default', eager: true },
)

export const REF_CREDITS = ${JSON.stringify(credits, null, 2)}

/** → () => Promise<url> for reference/<id>/<file>, or null when it was not bundled. */
export const refLoader = (id, file) => {
  const url = REF_URLS[\`../../reference/\${id}/\${file}\`]
  return url ? () => Promise.resolve(url) : null
}
export const refCredit = (id, file) => REF_CREDITS[\`\${id}/\${file}\`] || ''
`
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const text = generate()
  const old = existsSync(OUT) ? readFileSync(OUT, 'utf8') : ''
  if (process.argv.includes('--check')) {
    if (old !== text) {
      console.error('src/app/refs.js is stale — run `node tools/refs.mjs`')
      process.exit(1)
    }
    console.log('refs.js up to date')
  } else {
    writeFileSync(OUT, text)

    console.log(`wrote ${OUT.slice(PKG.length + 1)} (${Object.keys(scanRefs()).length} artifacts)`)
  }
}
